import{_ as r,C as E,o,c as e,a2 as a,b as n,w as t,a as s,E as A,a3 as C}from"./chunks/framework.BBdhqAg0.js";const B="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",D=JSON.parse('{"title":"인사 평가 및 승진","description":"","frontmatter":{},"headers":[],"relativePath":"hr-manage/evaluation.md","filePath":"hr-manage/evaluation.md","lastUpdated":1793125168000}'),u={name:"hr-manage/evaluation.md"};function g(m,l,d,c,_,p){const i=E("Mermaid");return o(),e("div",null,[l[1]||(l[1]=a('<h1 id="인사-평가-및-승진" tabindex="-1">인사 평가 및 승진 <a class="header-anchor" href="#인사-평가-및-승진" aria-label="Permalink to &quot;인사 평가 및 승진&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+B+'" alt="인사 평가 및 승진 심사 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/evaluation.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>인사 평가 및 승진</strong>은 사내 직급별 승급 정책(최소 근속 연한 및 필수 평가 등급)을 수립하고, 정기 인사 고과에 따른 업적 평가와 승진 심사 대상자 선발 및 인사 발령을 원스톱으로 처리하는 본사 인사 모듈입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[본사 관리] → [인사 조직 관리] → [인사 평가 및 승진]**을 선택하여 접속합니다. (평가 기간 동안 전 임직원 자기 평가 참여 지원, 심사는 인사 위원회 전용)</li></ul>',4)),(o(),n(C,null,{default:t(()=>[A(i,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%E2%9A%99%EF%B8%8F%201.%20%EC%8A%B9%EA%B8%89%20%EC%A0%95%EC%B1%85%20%EC%88%98%EB%A6%BD%3Cbr%3E(%EC%A7%81%EA%B8%89%EB%B3%84%20%EC%B5%9C%EC%86%8C%20%EC%97%B0%ED%95%9C%20%26%20%EA%B0%80%EC%82%B0%EC%A0%90%20%EA%B8%B0%EC%A4%80%ED%91%9C)%22%5D%20--%3E%20C%5B%22%F0%9F%8E%AF%203.%20%EC%8A%B9%EC%A7%84%20%EC%8B%AC%EC%82%AC%20%EB%8C%80%EC%83%81%20%EC%9E%90%EB%8F%99%20%EC%B6%94%EC%B2%9C%22%5D%0A%20%20%20%20B%5B%22%F0%9F%93%9D%202.%20%EC%A0%95%EA%B8%B0%20%EC%9D%B8%EC%82%AC%20%ED%8F%89%EA%B0%80%3Cbr%3E(%EC%9E%90%EA%B8%B0%20%ED%8F%89%EA%B0%80%20%E2%86%92%201%EC%B0%A8%20%ED%8C%80%EC%9E%A5%20%E2%86%92%202%EC%B0%A8%20%EC%9E%84%EC%9B%90)%22%5D%20--%3E%20C%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%8F%9B%EF%B8%8F%204.%20%EC%8A%B9%EC%A7%84%20%EC%8B%AC%EC%82%AC%20%EC%9C%84%EC%9B%90%ED%9A%8C%20%EC%8B%AC%EC%9D%98%3Cbr%3E(%EB%8B%A4%EB%A9%B4%20%ED%8F%89%EA%B0%80%2C%20%EA%B3%B5%EC%A0%81%2C%20%ED%8A%B9%EC%9D%B4%EC%82%AC%ED%95%AD%20%EB%B0%98%EC%98%81)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E2%9C%85%205.%20%EC%8A%B9%EC%A7%84%20%ED%99%95%EC%A0%95%20%26%20%EC%9D%B8%EC%82%AC%20%EB%B0%9C%EB%A0%B9%20%EC%9E%90%EB%8F%99%20%EC%97%B0%EA%B3%84%22%5D%0A"})]),fallback:t(()=>[...l[0]||(l[0]=[s(" Loading... ",-1)])]),_:1})),l[2]||(l[2]=a('<h2 id="_1-승급-정책-설정-promotion-policy" tabindex="-1">1. 승급 정책 설정 (Promotion Policy) <a class="header-anchor" href="#_1-승급-정책-설정-promotion-policy" aria-label="Permalink to &quot;1. 승급 정책 설정 (Promotion Policy)&quot;">​</a></h2><p>회사의 취업규칙 및 인사 규정에 맞추어 각 직급별 승진에 필요한 필수 요건과 기준 점수를 설정합니다.</p><ul><li><strong>직급별 표준 체류 연한</strong>: <ul><li>각 직급(사원 → 대리 → 과장 → 차장 → 부장)에서 다음 상위 직급으로 승진하기 위한 최소 근속 연수를 지정합니다.</li></ul></li><li><strong>평가 등급 환산 기준</strong>: <ul><li>S등급, A등급, B등급, C등급, D등급 등 상대/절대 평가 등급에 따른 배점 기준표를 정의하여 심사 종합 점수에 반영합니다.</li></ul></li><li><strong>발탁 승진 요건</strong>: <ul><li>탁월한 성과를 창출한 특례 승진 후보자를 위해 표준 체류 연한 미달 시에도 추천할 수 있는 특별 공적 기준을 마련할 수 있습니다.</li></ul></li></ul><h2 id="_2-인사-업적-평가-evaluations" tabindex="-1">2. 인사 업적 평가 (Evaluations) <a class="header-anchor" href="#_2-인사-업적-평가-evaluations" aria-label="Permalink to &quot;2. 인사 업적 평가 (Evaluations)&quot;">​</a></h2><p>분기, 반기 또는 연간 단위로 진행되는 직무 역량 및 업적 평가 프로세스를 지원합니다.</p><ul><li><strong>3단계 다면 평가 프로세스</strong>: <ol><li><strong>자기 평가 (본인 평가)</strong>: 피평가자 본인이 설정한 핵심 업무 목표 대비 달성도와 성과를 기술하고 자가 진단합니다.</li><li><strong>1차 평가 (부서장 / 팀장)</strong>: 직속 상급자가 실무 수행 능력, 직무 태도, 팀 기여도를 평가하고 코칭 피드백을 작성합니다.</li><li><strong>2차 평가 (상위 임원 / 본부장)</strong>: 부서 간 균형과 전사 기여도를 고려하여 종합 등급을 최종 확정합니다.</li></ol></li><li><strong>평가 지표 구성</strong>: <ul><li>핵심 성과 지표(KPI) 달성도, 직무 전문성, 협업 및 커뮤니케이션, 리더십 등 직급별 가중치에 맞춰 유연하게 지표를 구성할 수 있습니다.</li></ul></li></ul><h2 id="_3-승진-심사-대상-관리-promotions" tabindex="-1">3. 승진 심사 대상 관리 (Promotions) <a class="header-anchor" href="#_3-승진-심사-대상-관리-promotions" aria-label="Permalink to &quot;3. 승진 심사 대상 관리 (Promotions)&quot;">​</a></h2><p>설정된 승급 정책과 누적된 인사 평가 점수를 바탕으로 정기 승진 대상자를 시스템이 자동으로 산출하고 심사합니다.</p><ul><li><strong>후보자 자동 추천 엔진</strong>: <ul><li>직급별 최소 근속 연수를 충족하고 누적 평가 점수가 사내 기준치를 만족하는 임직원을 시스템이 자동 필터링하여 후보군 목록으로 제시합니다.</li></ul></li><li><strong>심사 위원회 의견 수렴</strong>: <ul><li>승진 심사 위원들이 후보자별 업무 성과, 주요 공적, 근태 현황, 교육 이수 내역을 종합 검토하고 최종 승진 승인 여부를 결정합니다.</li></ul></li><li><strong>인사 발령 자동 연계 (One-click Update)</strong>: <ul><li>승진 심사가 최종 확정되면, 시스템이 자동으로 신규 직급 및 직위가 반영된 공식 <strong>인사 발령</strong>을 생성하여 조직도와 인사 기록 대장에 즉시 반영합니다.</li></ul></li></ul><h2 id="_4-신입사원을-위한-자기-평가-작성-팁" tabindex="-1">4. 신입사원을 위한 자기 평가 작성 팁 <a class="header-anchor" href="#_4-신입사원을-위한-자기-평가-작성-팁" aria-label="Permalink to &quot;4. 신입사원을 위한 자기 평가 작성 팁&quot;">​</a></h2><ul><li><strong>구체적 수치와 근거 중심 작성</strong>: <ul><li>&quot;열심히 일했습니다&quot;라는 정성적 서술보다는 &quot;A 프로젝트 완료율 100% 달성&quot;, &quot;현장 인허가 지연 0건 처리&quot; 등 구체적인 실적과 산출물을 중심으로 작성하는 것이 좋은 평가를 받는 핵심 팁입니다.</li></ul></li><li><strong>IBS 시스템 내 활동 내역 링크 활용</strong>: <ul><li>자신이 주도한 주요 <a href="/work-manage/issue.html">업무(Issue)</a>나 확정된 <a href="/work-manage/meeting.html">회의록</a> 번호를 자기 평가서에 기재해 두면 평가자가 실질적인 성과를 즉시 검토할 수 있습니다.</li></ul></li><li><strong>기한 준수</strong>: <ul><li>1차 평가자의 검토 일정을 고려하여 안내된 자기 평가 마감일 최소 하루 전에 작성을 완료하고 제출하십시오.</li></ul></li></ul>',11))])}const b=r(u,[["render",g]]);export{D as __pageData,b as default};
